const activities={水:[['沿河散步','在公共步道慢慢走，选一段双方都方便的路线。','轻松聊天 · 公共空间'],['水边看展','看展后顺路逛逛水岸，不需要运动基础。','安静认识 · 新手友好'],['轻松游泳','双方都会游泳、都愿意时，选择有救生员的正规泳池。','先确认技能 · 费用另议']],木:[['公园漫步','选一条绿荫小路，不赶时间，也不用准备装备。','低门槛 · 公共空间'],['植物园打卡','一起认识几种植物，把聊天放在自然里。','户外 · 提前查天气'],['木作体验','找一个初学者也能参与的手工课程。','需预约 · 预算先确认']],火:[['看一场演出','选彼此都感兴趣的小型现场，再交流感受。','先确认兴趣'],['轻松跳舞','新手体验课，用好玩的方式认识彼此。','不要求基础'],['一起烘焙','分工完成一道甜点，看看合作的感觉。','手作 · 费用先确认']],土:[['陶艺体验','从一团泥开始，不用急着把话说满。','新手友好'],['一起做饭','可以从公共烹饪体验课开始认识。','共同完成 · 不要求去家里'],['逛市集','边走边看，发现彼此喜欢的小东西。','轻松 · 不赶时间']],金:[['羽毛球体验','提前商量强度，新手也可以轻松打。','运动 · 双方确认技能'],['手工首饰','选一堂基础课程，一起做件小作品。','手作 · 可留纪念'],['射箭体验','有教练指导的正规场馆，先体验再决定。','需预约 · 新手课']]};
function today(){const pillar=currentPillar(),d=new Date(state.date+'T12:00:00');return `<div class="page-top"><div><span class="eyebrow">A SMALL RITUAL FOR EVERY DAY</span><h1>某一天，遇见一种新的可能。</h1><p>看看当天的历法信息，再选一种想和朋友一起做的事。</p></div><label class="date-box">想看哪一天？<input type="date" id="calendar-date" value="${state.date}" min="1900-01-01" max="2100-12-31"></label></div><div class="calendar-grid"><section class="panel date-card"><span class="eyebrow">${d.getFullYear()} · ${String(d.getMonth()+1).padStart(2,'0')}</span><div class="calendar-day">${d.getDate()}</div><h2>${pillar}日</h2><p>公历 ${state.date}<br>${['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][d.getDay()]}</p><div class="calendar-status"><b>黄历宜忌 · 等待数据接入</b><br>“宜搬家、宜出行”等为通用历书栏目，当前不生成示例宜忌冒充真实结果。</div></section><section class="panel"><span class="eyebrow">CHOOSE YOUR ELEMENT</span><h2 style="font:29px var(--serif);font-weight:400;line-height:1.6">今天，给生活一点<br>${state.theme==='水'?'流动的空间':state.theme==='木'?'自然的生机':state.theme==='火'?'热闹的温度':state.theme==='土'?'踏实的体验':'清爽的节奏'}。</h2><p class="description">你提到的“补${state.theme}”，可以先成为选择活动的文化主题。<br>先选你真正想做的事，再邀请感兴趣的人。</p><div class="chips">${['水','木','火','土','金'].map(t=>`<button data-theme="${t}" class="${state.theme===t?'on':''}">${t} · ${t==='水'?'流动':t==='木'?'生长':t==='火'?'热情':t==='土'?'踏实':'专注'}</button>`).join('')}</div><p class="wide-info">这里是按自选五行主题整理的活动灵感，不是根据你命盘得出的喜忌。后续个人日期解读需同时核对完整命盘与当日资料。通用黄历与个人解读会分别呈现。</p></section></div><div class="section-head" style="margin-top:30px"><h2>${state.theme}主题 · 可以一起做的事</h2><span>活动类别示意，未查实时商家</span></div><div class="activity-list">${activities[state.theme].map(([name,desc,tag],i)=>`<article class="activity"><span class="number">0${i+1}</span><h3>${name}</h3><p>${desc}</p><span class="chip">${tag}</span><button class="outline full" style="margin-top:20px" data-activity="${i}">邀请一个人一起去 ↗</button></article>`).join('')}</div>`;}
function invite(){return `<div class="page-top"><div><span class="eyebrow">AN INVITATION FOR TWO</span><h1>想认识TA，先看看你们的关系。</h1><p>各自私密填写，双方授权后查看；不用先互相透露完整生辰。</p></div></div><div class="invite-layout"><section class="invite-explainer"><span class="eyebrow">FRIENDS · COMPANIONS · PARTNERS</span><h2>你和我放在一起，<br>会是什么样？</h2><p>从五行关系开始，也了解彼此欣赏的地方、支持的方式，以及值得聊清楚的不同。</p>${[['01','你先填写自己的资料'],['02','邀请TA独立填写并授权'],['03','查看双人解读，决定下一步']].map(([n,t])=>`<div class="step"><b>${n}</b>${t}</div>`).join('')}<p class="subtle">原始生辰不进入公开卡。受邀人可以只参与这一次，不加入交友匹配。</p></section><section class="panel"><h2 style="font:24px var(--serif)">先填写我这一份</h2><form id="inviter-form"><label class="field">我的昵称<input name="name" value="${esc(state.my.name)}" maxlength="30" required></label><div class="two"><label class="field">公历生日<input type="date" name="birth" min="1900-01-01" max="${adultLimit()}" required></label><label class="field">出生时间（可不填）<input type="time" name="time"></label></div><label class="field">出生城市<input name="city" maxlength="60" placeholder="如：吉林长春；不需要家庭地址"></label><label class="field">我们想了解<select name="purpose"><option>朋友相处</option><option>一起活动</option><option>恋爱与长期关系</option></select></label><label class="check"><input type="checkbox" required>我已成年，同意在本地演示中计算日柱；这不会自动加入交友池。</label><p class="form-note">当前为流程预览，出生日期仅用于本地简算，不保存。完整四柱校时、服务端邀请与隐私隔离尚未接通。</p><button class="primary full">预览受邀方如何填写 →</button></form></section></div>`;}
function adultLimit(){const now=new Date();return `${now.getFullYear()-18}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;}
const profileFields=[['age','年龄'],['height','身高（cm）'],['weight','体重（kg）'],['school','学校与学历'],['job','单位 / 职业 / 编制、私企'],['income','税前年收入区间'],['assets','A几 / 金额区间 / 个人或家庭归属'],['house','房产归属及贷款情况'],['car','车辆情况'],['mbti','MBTI'],['zodiac','星座'],['highlight','我的亮点与相处价值'],['wish','想一起做的事']];
profileFields.splice(5,0,['industry','行业'],['title','职级 / Title']);
profileFields.splice(0,0,['chineseZodiac','生肖'],['wantedZodiac','想认识的生肖（可多个，用顿号分隔）']);
function myPage(){const p=state.my;return `<div class="page-top"><div><span class="eyebrow">A CARD THAT FEELS LIKE YOU</span><h1>把你的亮点，认真介绍出去。</h1><p>只展示你愿意公开的内容。生辰、家庭住址不出现在卡片上。</p></div><button class="outline" data-action="profile">编辑资料与公开范围 ↗</button></div><div class="profile-summary"><article class="public-card"><div class="section-head"><span style="font:31px Georgia">runae.</span><span>本地预览 · 未发布</span></div>${p.photo?`<img src="${esc(p.photo)}" alt="本人选择的本地照片" style="width:100%;height:220px;object-fit:cover;border-radius:10px;margin:15px 0">`:''}<h1>${esc(p.name)} <small style="font:12px sans-serif">${esc(p.city)} · ${p.intent}</small></h1><div class="preference">我是${stemLabel(p.stem)}，想认识${stemLabel(p.wanted)}的你。</div><dl class="facts">${profileFields.filter(([k])=>state.vis[k]==='公开'&&p[k]).map(([k,label])=>`<dt>${label}</dt><dd>${esc(p[k])}${k==='height'?'cm':k==='weight'?'kg':k==='age'?'岁':''}</dd>`).join('')}</dl><h2>想找五行互补的搭子或对象？</h2><p class="description">输入你的出生信息，查日主，生成你的交友卡。<br>已有心仪的人？邀请TA一起合盘。</p><p class="form-note">信息本人填写，未核验；示例档案不代表真实用户。传统文化参考，不保证关系结果。</p></article><div class="actions" style="margin-top:16px"><button class="primary" data-action="copy">复制公开分享文案</button><button class="outline" data-action="export">保存公开分享图片</button><button class="outline" data-page="invite">邀请TA合盘</button></div><p class="subtle">这是本地预览，不能创建可访问的真实邀请链接。未公开字段不会出现在上方卡片、复制文案或导出图片中。</p></div>`;}
function profileEditor(){
 showModal(`<span class="eyebrow">MY PUBLIC PROFILE</span><h2>资料完整，公开由你选。</h2><p>资产、收入、身高、体重、学校、年龄、职业、行业、职级为必填。自由职业、个体经营、在读等可如实填写；填写不等于认证。</p><form id="profile-form"><div class="two"><label class="field">昵称<input name="name" value="${esc(state.my.name)}" required maxlength="30"></label><label class="field">城市<input name="city" value="${esc(state.my.city)}" required maxlength="30"></label></div><label class="field">交友目的<select name="intent">${['找朋友','找搭子','找对象'].map(t=>`<option ${state.my.intent===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="two"><label class="field">我的日主（本地示例可改）<select name="stem" required>${GAN.map(g=>`<option value="${g}" ${state.my.stem===g?'selected':''}>${stemLabel(g)}</option>`).join('')}</select></label><label class="field">想认识的日主 *<select name="wanted" required>${GAN.map(g=>`<option value="${g}" ${state.my.wanted===g?'selected':''}>${stemLabel(g)}</option>`).join('')}</select></label></div><p class="form-note">正式版先给出完整八字分析支持的方向，再由本人确认；本地示例可手动修改偏好，未执行完整合盘。</p>${profileFields.filter(([k])=>k!=='wish').map(([k,t])=>`<label class="field">${t}${requiredProfileFields.includes(k)?' *':''}<input name="${k}" value="${esc(state.my[k])}" maxlength="${k==='highlight'?160:100}" ${requiredProfileFields.includes(k)?'required':''} ${['age','height','weight'].includes(k)?`type="number" min="${k==='age'?18:k==='height'?100:25}" max="${k==='age'?100:k==='height'?240:250}"`:''}><span class="visibility">选择谁能看到<select name="vis-${k}">${['公开','双方有意后解锁','仅后台匹配'].map(t=>`<option ${state.vis[k]===t?'selected':''}>${t}</option>`).join('')}</select></span></label>`).join('')}<fieldset style="border:1px solid #d6ddcd;border-radius:9px;padding:15px;margin-top:20px"><legend>从自己的爱好里选活动 *</legend>${hobbyOptions.map(t=>`<label class="check" style="display:inline-flex;margin:7px 10px 7px 0"><input type="checkbox" name="hobbies" value="${t}" ${state.my.wish.split(/[、,，]/).includes(t)?'checked':''}>${t}</label>`).join('')}<label class="field">其他爱好（选填，顿号分隔）<input name="otherHobby" maxlength="60" value="${esc(state.my.wish.split(/[、,，]/).filter(t=>!hobbyOptions.includes(t)).join('、'))}"></label><label class="visibility">爱好的公开范围<select name="vis-wish">${['公开','双方有意后解锁','仅后台匹配'].map(t=>`<option ${state.vis.wish===t?'selected':''}>${t}</option>`).join('')}</select></label></fieldset><label class="field">上传本人照片（选填，本地预览）<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label><label class="check"><input type="checkbox" name="photoPublic">我同意将这次选择的照片放在公开卡片中</label><label class="check"><input type="checkbox" name="joined" ${state.joined?'checked':''}>愿意加入交友推荐（仅记录本次演示选择，不实际提交）</label><label class="check"><input type="checkbox" required>我确认公开内容真实且愿意展示；学校、单位与资产目前未认证。</label><button class="primary full">保存并预览公开卡片</button><button type="button" class="outline full" style="margin-top:9px" data-action="removePhoto">移除已有公开照片</button></form>`);
}
const originalMyPage=myPage;
myPage=function(){
 const cards=[['house','房产','房产归属、自住/租住等由本人说明'],['car','车辆','车型、个人或家庭使用等由本人说明']].map(([kind,label,hint])=>{
  const visible=state.vis[kind]==='公开'&&state.my[kind+'PhotoPublic']&&state.my[kind+'Photo'];
  return `<article class="property-item"><div class="property-image">${visible?`<img src="${esc(state.my[kind+'Photo'])}" alt="本人选择公开的${label}照片">`:`<span>${kind==='house'?'⌂':'◇'}</span><small>${label}照片未公开展示</small>`}</div><b>${label} · 本人展示</b><p>${state.vis[kind]==='公开'&&state.my[kind]?esc(state.my[kind]):hint}</p><small>照片不等于产权或资产认证</small></article>`;
 }).join('');
 return originalMyPage().replace('</dl>',`</dl><section class="property-section"><div class="section-head"><h2>房产与车辆</h2><button class="link" data-action="profile">上传或调整权限 ↗</button></div><div class="property-grid">${cards}</div><p class="form-note">房车展示可选，不强制公开。仅本人允许公开的文字和图片才会出现在这里。</p></section>`);
};
const originalProfileEditor=profileEditor;
profileEditor=function(){
 originalProfileEditor();const form=$('#profile-form');if(!form||typeof form.querySelector!=='function')return;
 const wanted=form.elements.wanted;if(!GAN.includes(state.my.wanted)){const option=document.createElement('option');option.value='';option.textContent='等待分析后确认，或选择个人偏好';wanted.prepend(option);wanted.value='';}
 const section=document.createElement('fieldset');section.className='property-upload';section.innerHTML='<legend>展示房产和车辆（选填）</legend><p class="form-note">可以拍生活空间或车辆，但不要求公开地址、门牌、车牌、证件等信息。说明个人/家庭所有、租住或仅使用，不能凭照片获得资产认证。</p>'+[['house','房产'],['car','车辆']].map(([kind,label])=>`<label class="field">${label}照片<input type="file" name="${kind}Photo" accept="image/jpeg,image/png,image/webp"></label><div class="property-preview" id="preview-${kind}">${state.my[kind+'Photo']?`<img src="${esc(state.my[kind+'Photo'])}" alt="我的${label}照片预览">`:'尚未上传照片'}</div><label class="check"><input type="checkbox" name="${kind}PhotoPublic" ${state.my[kind+'PhotoPublic']?'checked':''}>允许在公开交友卡展示这张${label}照片</label><p class="form-note">还需将上方“${label==='房产'?'房产归属及贷款情况':'车辆情况'}”公开范围设为“公开”；否则照片仍不公开。</p>`).join('');
 form.querySelector('.primary.full').before(section);const tempUrls=[];
 for(const kind of ['house','car']){form.elements[kind+'Photo'].onchange=()=>{const f=form.elements[kind+'Photo'].files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024){toast('请选择10MB以内的JPEG、PNG或WebP照片');return;}const url=URL.createObjectURL(f);tempUrls.push(url);const img=document.createElement('img');img.src=url;img.alt='仅本地预览';$('#preview-'+kind).replaceChildren(img);};}
 $('#dialog').addEventListener('close',()=>tempUrls.forEach(url=>URL.revokeObjectURL(url)),{once:true});
};
function detail(id){const p=people.find(p=>p.id===id);showModal(`<span class="eyebrow">虚构档案 · 所有条件未核验</span><h2>${p.name} · ${p.age}岁 · ${p.intent}</h2><div class="tag-row">${chips([stemLabel(p.stem),p.mbti,p.zodiac])}</div><p>${p.bio}</p><dl class="facts">${[['身高体重',p.height+'cm / '+p.weight+'kg'],['学校学历',p.school],['职业单位',p.job+' · '+p.kind],['年收入',p.income],['资产',p.assets],['房产',p.house],['车辆',p.car],['想一起',p.wish]].map(([a,b])=>`<dt>${a}</dt><dd>${b}</dd>`).join('')}</dl><button class="primary full" data-pair="${p.id}">看看我们的关系 →</button>`);}
function pairResult(other){showModal(`<span class="eyebrow">双人关系预览 · 非完整合盘</span><h2>你和${esc(other.name)}放在一起，<br>会是什么样？</h2><div class="result-pair"><div>${state.my.stem}<span> ${esc(state.my.name)}</span></div><b>＋</b><div>${other.stem}<span> ${esc(other.name)}</span></div></div><div class="result-steps"><div><b>五行基础关系：${relation(state.my.stem,other.stem)}</b>仅比较日主所属五行，没有据此推断关系成败、喜忌或谁会旺谁。</div><div><b>完整合盘将展开什么？</b>五行互补与四柱关系、彼此支持的方式、相处时值得提前交流的不同。需完整出生资料和实际分析，当前不虚构结论。</div><div><b>先聊一个具体的问题</b>“你最喜欢怎样度过周末？想和朋友一起尝试什么？”</div></div><p class="form-note">原型中的双方同意、语音和活动流程都不触发真实联系。</p><div class="actions"><button class="primary" data-action="voice">先体验15分钟语音安排</button><button class="outline" data-action="datePlan">一起选个活动</button></div>`);}
function publicText(){return [`${state.my.city}｜${state.my.intent}`,state.my.name,`我是${stemLabel(state.my.stem)}，想认识${stemLabel(state.my.wanted)}的你。`,...profileFields.filter(([k])=>state.vis[k]==='公开'&&state.my[k]).map(([k,t])=>`${t}：${state.my[k]}`),'想找五行互补的搭子或对象？查日主，生成你的交友卡。','本人填写，未核验；本地预览尚未发布。传统文化参考。'].join('\n');}
function birth(){showModal(`<span class="eyebrow">YOUR DAY MASTER</span><h2>从认识自己的日主开始。</h2><form id="birth-form"><label class="field">公历出生日期<input name="birth" type="date" min="1900-01-01" max="${adultLimit()}" required></label><p class="form-note">复用现有仓库日柱简算口径；公历、北京时间日期。临近午夜、境外出生或需要校时的情况应进一步核对；不支持农历转换。完整排盘尚未接入。</p><label class="check"><input type="checkbox" required>我已成年，同意仅在本页面计算；生辰不保存、不公开，也不自动加入匹配。</label><button class="primary full">免费查看我的日主</button></form>`);}
function bindForms(){const cal=$('#calendar-date');if(cal)cal.onchange=()=>{if(!cal.value||!cal.checkValidity())return;state.date=cal.value;render();};const form=$('#inviter-form');if(form)form.onsubmit=e=>{e.preventDefault();const f=new FormData(form);const stem=dayPillar(...f.get('birth').split('-').map(Number))[0];state.inviter={name:f.get('name'),stem};showModal(`<span class="eyebrow">受邀方视角 · 仅模拟</span><h2>${esc(f.get('name'))}邀请你，<br>一起看看你们的关系。</h2><form id="recipient-form"><label class="field">你的昵称<input name="name" required maxlength="30"></label><label class="field">你的公历生日<input type="date" name="birth" min="1900-01-01" max="${adultLimit()}" required></label><label class="check"><input type="checkbox" required>我已成年，同意本地计算日柱并向双方展示日主关系。不公开完整生辰。</label><p class="form-note">真实邀请链接与服务端隐私隔离未接通；这是同一浏览器模拟，不是向另一位用户发送邀请。</p><button class="primary full">查看日主基础关系</button></form>`);$('#recipient-form').onsubmit=ev=>{ev.preventDefault();const r=new FormData($('#recipient-form'));const g=dayPillar(...r.get('birth').split('-').map(Number))[0];const own=state.inviter;showModal(`<h2>${esc(own.name)} ＋ ${esc(r.get('name'))}</h2><div class="result-pair"><div>${own.stem}<span>${WX[GAN.indexOf(own.stem)]}</span></div><b>＋</b><div>${g}<span>${WX[GAN.indexOf(g)]}</span></div></div><p>日主基础关系：${relation(own.stem,g)}。这不是完整合盘，不能据此判断是否适合在一起。</p><p>后续完整报告将核对双方四柱、出生地与时间；现实中的关系期待另由双方问卷了解。</p><a class="primary full" href="pair.html">查看完整结果页的设计样稿 ↗</a><p class="form-note">本次不保存生日，不发出邀请，也不加入交友池。</p>`);state.inviter=null;};};}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.page){$('#dialog').close();navigate(b.dataset.page);return;}
 if(b.dataset.intent){state.intent=b.dataset.intent;render();return;}
 if(b.dataset.theme){state.theme=b.dataset.theme;render();return;}
 if(b.dataset.person){detail(Number(b.dataset.person));return;}
 if(b.dataset.pair){pairResult(people.find(p=>p.id===Number(b.dataset.pair)));return;}
 if(b.dataset.pick){state.wanted=b.dataset.pick;$('#dialog').close();render();return;}
 if(b.dataset.activity){const item=activities[state.theme][Number(b.dataset.activity)];showModal(`<h2>想和谁一起${item[0]}？</h2><p>先发出邀请，双方同意后，再商量预算、时间与各自方便的出发商圈。</p>${people.map(p=>`<button class="outline full" style="margin-top:10px" data-pair="${p.id}">${p.name} · ${stemLabel(p.stem)} · 查看关系与下一步 →</button>`).join('')}<p class="form-note">当前没有真实用户消息或场馆预订。</p>`);return;}
 switch(b.dataset.action){case'birth':birth();break;case'profile':profileEditor();break;case'reset':state.intent='全部';state.wanted='全部';render();break;case'filter':showModal(`<h2>想认识哪一种日主？</h2><p>自主选择交友偏好，不按生克直接判断好坏。</p><div class="chips"><button data-pick="全部">不限日主</button>${GAN.map(g=>`<button data-pick="${g}">${stemLabel(g)}</button>`).join('')}</div>`);break;
 case'removePhoto':if(state.my.photo)URL.revokeObjectURL(state.my.photo);state.my.photo='';toast('公开照片已移除，保存资料后查看');break;
 case'voice':showModal('<h2>先聊15分钟，再决定见面。</h2><form id="voice-form"><label class="field">聊天方式<select><option>语音</option><option>视频</option></select></label><label class="field">方便的时间<input type="datetime-local" required></label><div class="result-steps"><div><b>可以聊什么？</b>最近的周末怎么过？最想一起尝试哪件事？交朋友时最看重什么？</div></div><button class="primary full">保存本次演示选择</button><p class="form-note">正式安排需对方确认；不会实际接通、发消息或创建日历事件。</p></form>');$('#voice-form').onsubmit=ev=>{ev.preventDefault();$('#dialog').close();toast('已体验排期选择，未向对方发送安排');};break;
 case'datePlan':showModal('<h2>一起做点喜欢的事。</h2><p>两人各自填写出发地铁站／商圈，不交换家庭住址，再共同确认活动。</p><a href="share.html" class="primary full">打开私密约会安排原型 ↗</a><button class="outline full" style="margin-top:10px" data-page="today">先看五行主题活动</button><p class="form-note">约会原型中选择“一起安排一次见面”，可体验双方填写位置的流程。</p>');break;
 case'copy':try{await navigator.clipboard.writeText(publicText());toast('只含公开字段的分享文案已复制');}catch{showModal('<h2>复制公开文案</h2><textarea id="public-copy" rows="14" style="width:100%"></textarea>');$('#public-copy').value=publicText();$('#public-copy').select();}break;
 case'export':exportCard();break;}
});
document.addEventListener('submit',e=>{if(e.target.id==='birth-form'){e.preventDefault();const f=new FormData(e.target),g=dayPillar(...f.get('birth').split('-').map(Number));state.my.stem=g[0];showModal(`<h2>你的日主是 ${stemLabel(g[0])}。</h2><p>日柱：${g}。日主是认识彼此的一个起点，不是关系适配的全部依据。</p><button class="primary full" data-action="profile">填写亮点，生成我的卡 →</button><p class="form-note">本次公历简算，原始出生日期未保存。</p>`);}
 if(e.target.id==='profile-form'){
  e.preventDefault();const f=new FormData(e.target),hobbies=[...f.getAll('hobbies'),...String(f.get('otherHobby')||'').split(/[、,，]/).map(t=>t.trim()).filter(Boolean)];
  if(requiredProfileFields.some(k=>!String(f.get(k)||'').trim())){toast('请补齐带星号的必填资料');return;}
  const animals=[...'鼠牛虎兔龙蛇马羊猴鸡狗猪'];if(String(f.get('wantedZodiac')).split(/[、,，]/).some(t=>!animals.includes(t.trim().replace(/^属/,'')))){toast('想认识的生肖请填写十二生肖，可用顿号分隔');return;}
  if(!hobbies.length){toast('至少选择或填写一项自己的爱好');return;}
  const image=f.get('photo');if(image&&image.size&&f.has('photoPublic')&&(!['image/jpeg','image/png','image/webp'].includes(image.type)||image.size>10*1024*1024)){toast('请选择10MB以内的JPEG、PNG或WebP照片');return;}
  for(const kind of ['house','car']){const asset=f.get(kind+'Photo');if(asset&&asset.size&&(!['image/jpeg','image/png','image/webp'].includes(asset.type)||asset.size>10*1024*1024)){toast('房车照片请选择10MB以内的JPEG、PNG或WebP');return;}}
  for(const kind of ['house','car']){const asset=f.get(kind+'Photo');if(asset&&asset.size){if(state.my[kind+'Photo'])URL.revokeObjectURL(state.my[kind+'Photo']);state.my[kind+'Photo']=URL.createObjectURL(asset);}state.my[kind+'PhotoPublic']=f.has(kind+'PhotoPublic');}
  for(const k of ['name','city','intent','stem','wanted'])state.my[k]=f.get(k).trim();for(const[k]of profileFields){state.my[k]=k==='wish'?[...new Set(hobbies)].join('、'):String(f.get(k)||'').trim();state.vis[k]=f.get('vis-'+k);}state.joined=f.has('joined');if(image&&image.size&&f.has('photoPublic')){if(state.my.photo)URL.revokeObjectURL(state.my.photo);state.my.photo=URL.createObjectURL(image);}$('#dialog').close();navigate('me');toast('公开卡片已更新，仅保留在当前页面');
 }
});
function exportCard(){const lines=publicText().split('\n'),canvas=document.createElement('canvas'),c=canvas.getContext('2d');canvas.width=1080;canvas.height=450+lines.reduce((n,t)=>n+Math.max(1,Math.ceil(t.length/25))*60,0);c.fillStyle='#f8f6ec';c.fillRect(0,0,canvas.width,canvas.height);c.strokeStyle='#cbd5bd';c.strokeRect(35,35,1010,canvas.height-70);c.fillStyle='#2d503d';c.font='60px Georgia';c.fillText('runae.',90,140);c.font='bold 40px "Microsoft YaHei",sans-serif';c.fillText('从五行，遇见想认识的人。',90,225);let y=320;c.font='30px "Microsoft YaHei",sans-serif';for(const t of lines){let line='';for(const ch of t){if(c.measureText(line+ch).width>890){c.fillText(line,90,y);y+=55;line='';}line+=ch;}c.fillText(line,90,y);y+=64;}canvas.toBlob(blob=>{if(!blob){toast('图片生成失败，请重试');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Runae-公开交友卡.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('已导出公开资料；照片不包含在本版文字卡中');},'image/png');}
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(['discover','today','invite','me'].includes(page)&&page!==state.page){state.page=page;render();}});
if(['discover','today','invite','me'].includes(location.hash.slice(1)))state.page=location.hash.slice(1);
render();
if(importedDraft){state.page='me';render();profileEditor();toast('已带入刚填写的亮点，请确认完整资料和公开范围');}
